idToContentMap.3.3.4#p21:
    The agenda is made up of 
    time segments.  Each time segment is a
    pair consisting of a number (the time) and a 

    queue (see
    exercise 3.32) that holds the
    functions
    that are scheduled to be run during that time segment.
    function make_time_segment(time, queue) {
   return pair(time, queue);
}
function segment_time(s) { return head(s); }

function segment_queue(s) { return tail(s); } 
    We will operate on the time-segment queues using the queue operations
    described in section 3.3.2.

idToContentMap.3.3.4#p22:
    The agenda itself is a one-dimensional

    table of time segments.  It
    differs from the tables described in section 3.3.3
    in that the segments will be sorted in order of increasing time.  In
    addition, we store the 
    current time (i.e., the time of the last action
    that was processed) at the head of the agenda.  A newly constructed
    agenda has no time segments and has a current time of 0:function make_agenda() { return list(0); }

function current_time(agenda) { return head(agenda); }

function set_current_time(agenda, time) {
   set_head(agenda, time);
}
function segments(agenda) { return tail(agenda); }

function set_segments(agenda, segs) {
   set_tail(agenda, segs);
}
function first_segment(agenda) { return head(segments(agenda)); }

function rest_segments(agenda) { return tail(segments(agenda)); }

idToContentMap.3.3.4#p23:
    An agenda is empty if it has no time segments:
    function is_empty_agenda(agenda) {
   return is_null(segments(agenda));
}

idToContentMap.3.3.4#p24:
    To add an action to an agenda, we first check if the agenda is empty.
    If so, we create a time segment for the action and install this in
    the agenda.  Otherwise, we scan the agenda, examining the time of each
    segment.  If we find a segment for our appointed time, we add the
    action to the associated queue.  If we reach a time later than the one
    to which we are appointed, we insert a new time segment into the
    agenda just before it.  If we reach the end of the agenda, we must
    create a new time segment at the end.
    function add_to_agenda(time, action, agenda) {
   function belongs_before(segs) {
      return is_null(segs) || time < segment_time(head(segs));
   }
   function make_new_time_segment(time, action) {
      const q = make_queue();
      insert_queue(q, action);
      return make_time_segment(time, q);
   }
   function add_to_segments(segs) {
      if (segment_time(head(segs)) === time) {
          insert_queue(segment_queue(head(segs)), action);
      } else {
          const rest = tail(segs);
          if (belongs_before(rest)) {
              set_tail(segs, pair(make_new_time_segment(time, action),
                                  tail(segs)));
          } else {
              add_to_segments(rest);
          }
      }
   }
   const segs = segments(agenda);
   if (belongs_before(segs)) {
       set_segments(agenda,
                    pair(make_new_time_segment(time, action), segs));
   } else {
       add_to_segments(segs);
   }
}

idToContentMap.3.3.4#p25:
    The
    function
    that removes the first item from the agenda deletes the
    item at the front of the queue in the first time segment.  If this
    deletion makes the time segment empty, we remove it from the list of
    segments:function remove_first_agenda_item(agenda) {
   const q = segment_queue(first_segment(agenda));
   delete_queue(q);
   if (is_empty_queue(q)) {
       set_segments(agenda, rest_segments(agenda));
   } else {}
}

idToContentMap.3.3.4#p26:
    The first agenda item is found at the head of the queue in the first
    time segment.  Whenever we extract an item, we also update the current
    time:function first_agenda_item(agenda) {
    if (is_empty_agenda(agenda)) {
        error("agenda is empty -- first_agenda_item");
    } else {
        const first_seg = first_segment(agenda);
        set_current_time(agenda, segment_time(first_seg));
        return front_queue(segment_queue(first_seg));
    }
}

idToContentMap.3.3.5#p5:
	To use the constraint system to carry out the temperature computation
	outlined above, we first call the constructor
	make_connector
	to create two connectors,
	C and F,
	and then link them in an appropriate network:
      const C = make_connector();
const F = make_connector();
celsius_fahrenheit_converter(C, F); 
    The
    function
    that creates the network is defined as follows:
    function celsius_fahrenheit_converter(c, f) {
    const u = make_connector();
    const v = make_connector();
    const w = make_connector();
    const x = make_connector();
    const y = make_connector();
    multiplier(c, w, u);
    multiplier(v, x, u);
    adder(v, y, f);
    constant(9, w);
    constant(5, x);
    constant(32, y);
    return "ok";
} 
    This
    function
    creates the internal connectors u,
    v, w,
    x, and y, and
    links them as shown in figure 3.28 using the
    primitive constraint constructors adder,
    multiplier, and
    constant.  Just as with the digital-circuit
    simulator of section 3.3.4, expressing
    these combinations of primitive elements in terms of
    functions
    automatically provides our language with a means of abstraction for compound
    objects.

idToContentMap.3.3.5#p11:
Adder constructs an adder constraint among
    summand connectors a1 and
    a2 and a sum
    connector.  An adder is implemented as a
    function
    with local state (the
    functionme below):
    function adder(a1, a2, sum) {
    function process_new_value() {
        if (has_value(a1) && has_value(a2)) {
            set_value(sum, get_value(a1) + get_value(a2), me);
        } else if (has_value(a1) && has_value(sum)) {
            set_value(a2, get_value(sum) - get_value(a1), me);
        } else if (has_value(a2) && has_value(sum)) {
            set_value(a1, get_value(sum) - get_value(a2), me);
        } else {}
    }
    function process_forget_value() {
        forget_value(sum, me);
        forget_value(a1, me);
        forget_value(a2, me);
        process_new_value();
    }
    function me(request) {
        if (request === "I have a value.") {
            process_new_value();
        } else if (request === "I lost my value.") {
            process_forget_value();
        } else {
            error(request, "unknown request -- adder");
        }
    }
    connect(a1, me);
    connect(a2, me);
    connect(sum, me);
    return me;
} 
	The function adder
    connects the new adder to the designated
    connectors and returns it as its value.  The
    functionme, which represents the adder, acts as a
    dispatch to the local
    functions.
    The following
    "syntax interfaces" (see
    footnote 2 in
    section 3.3.4) are used in conjunction
    with the dispatch:
    function inform_about_value(constraint) {
    return constraint("I have a value.");
}

function inform_about_no_value(constraint) {
    return constraint("I lost my value.");
} 
    The adder's local
    functionprocess_new_value
    is called when the adder is informed that one of its connectors has a value.
    The adder first checks to see if both a1 and
    a2 have values. If so, it tells
    sum to set its value to the sum of the two
    addends. The informant argument to
    set_value
    is me, which is the adder object itself.  If
    a1 and a2 do not
    both have values, then the adder checks to see if perhaps
    a1 and sum have
    values.  If so, it sets a2 to the difference of
    these two. Finally, if a2 and
    sum have values, this gives the adder enough
    information to set a1.  If the adder is told
    that one of its connectors has lost a value, it requests that all of its
    connectors now lose their values.  (Only those values that were set by
    this adder are actually lost.)  Then it runs
    process_new_value.

    The reason for this last step is that one or more connectors may still
    have a value (that is, a connector may have had a value that was not
    originally set by the adder), and these values may need to be
    propagated back through the adder.

idToContentMap.3.3.5#p12:
    A multiplier is very similar to an adder. It will set its
    product to 0 if either of the factors is 0,
    even if the other factor is not known.
    function multiplier(m1, m2, product) {
    function process_new_value() {
        if ((has_value(m1) && get_value(m1) === 0)
         || (has_value(m2) && get_value(m2) === 0)) {
            set_value(product, 0, me);
        } else if (has_value(m1) && has_value(m2)) {
            set_value(product, get_value(m1) * get_value(m2), me);
        } else if (has_value(product) && has_value(m1)) {
            set_value(m2, get_value(product) / get_value(m1), me);
        } else if (has_value(product) && has_value(m2)) {
            set_value(m1, get_value(product) / get_value(m2), me);
        } else {}
    }
    function process_forget_value() {
        forget_value(product, me);
        forget_value(m1, me);
        forget_value(m2, me);
        process_new_value();
    }
    function me(request) {
        if (request === "I have a value.") {
            process_new_value();
        } else if (request === "I lost my value.") {
            process_forget_value();
        } else {
            error(request, "unknown request -- multiplier");
        }
    }
    connect(m1, me);
    connect(m2, me);
    connect(product, me);
    return me;
} 
    A constant constructor simply sets the value of
    the designated connector.  Any
    "I have a value."
    or
    "I lost my value."
    message sent to the constant box will produce an error.
    function constant(value, connector) {
    function me(request) {
        error(request, "unknown request -- constant");
    }
    connect(connector, me);
    set_value(connector, value, me);
    return me;
} 
    Finally, a probe prints a message about the setting or unsetting of
    the designated connector:
    function probe(name, connector) {
    function print_probe(value) {
        display("Probe: " + name + " = " + stringify(value));
    }
    function process_new_value() {
        print_probe(get_value(connector));
    }
    function process_forget_value() {
        print_probe("?");
    }
    function me(request) {
        return request === "I have a value."
               ? process_new_value()
               : request === "I lost my value."
               ? process_forget_value()
               : error(request, "unknown request -- probe");
    }
    connect(connector, me);
    return me;
}

idToContentMap.3.3.5#p13:
    A connector is represented as a procedural object with local state variables
    value, the current value of the connector;
    informant, the object that set the
    connector's value; and constraints,
    a list of the constraints in which the connector participates.
    function make_connector() {
    let value = false;
    let informant = false;
    let constraints = null;
    function set_my_value(newval, setter) {
        if (!has_value(me)) {
            value = newval;
            informant = setter;
            return for_each_except(setter,
                                   inform_about_value,
                                   constraints);
        } else if (value !== newval) {
            error(list(value, newval), "contradiction");
        } else {
            return "ignored";
        }
    }
    function forget_my_value(retractor) {
        if (retractor === informant) {
            informant = false;
            return for_each_except(retractor,
                                   inform_about_no_value,
                                   constraints);
        } else {
            return "ignored";
        }
    }
    function connect(new_constraint) {
        if (is_null(member(new_constraint, constraints))) {
            constraints = pair(new_constraint, constraints);
        } else {}
        if (has_value(me)) {
            inform_about_value(new_constraint);
        } else {}
        return "done";
    }
    function me(request) {
        if (request === "has_value") {
            return informant !== false;
        } else if (request === "value") {
            return value;
        } else if (request === "set_value") {
            return set_my_value;
        } else if (request === "forget") {
            return forget_my_value;
        } else if (request === "connect") {
            return connect;
        } else {
            error(request, "unknown operation -- connector");
        }
    }
    return me;
}

idToContentMap.3.3.5#p14:
    The connector's local
    functionset_my_value
    is called when there is a request to set the connector's value.  If
    the connector does not currently have a value, it will set its value and
    remember as informant the constraint that
    requested the value to be set. Then the connector will
    notify all of its participating constraints except the constraint that
    requested the value to be set. This is accomplished using the following
    iterator, which applies a designated
    function
    to all items in a list except a given one:
    function for_each_except(exception, fun, list) {
    function loop(items) {
        if (is_null(items)) {
            return "done";
        } else if (head(items) === exception) {
            return loop(tail(items));
        } else {
            fun(head(items));
            return loop(tail(items));
        }
    }
    return loop(list);
}

